WITH sg AS (SELECT public.archi_project_signals($1::uuid) AS j), cd AS (SELECT public.archi_portfolio_cards($1::uuid) AS j) SELECT (SELECT e FROM sg, jsonb_array_elements(sg.j) e WHERE e->>'project_id' = m.project_id) AS sig, (SELECT j FROM cd) AS cards, m.project_id, m.contract_type, m.parent_project_id, m.visits_plan, m.visit_price, m.visits_done, m.contract_amount, m.planned_hours, m.actual_hours, m.profitability_plan_pct, m.profitability_forecast_pct, m.profit_plan, m.profit_forecast, m.earned_value_contract, m.acts_amount, m.actual_cost, m.stage_data, m.money_received, m.money_to_completion_team, m.money_to_completion_subcontract, m.hours_remaining, m.etc_forecast_total_hours, m.cpi_classic_evm, m.contract_file_url, m.forecast_confirmed_pct, m.forecast_confirmed_week, m.data_updated_at, s.week_start AS wr_week, s."готовність_pct" AS wr_readiness, s."залишок_прогноз_по_стадіях" AS wr_etc, s."дедлайн_прогноз_по_стадіях" AS wr_deadlines, s."ймовірність_акту" AS wr_act_prob, s."ймовірність_документації" AS wr_doc_prob, s.problems AS wr_problems, s.help_needed AS wr_help, regexp_replace(regexp_replace(trim(s.plans_next_week), '\s*;\s*|\s+(?=\d{1,2}\)\s)', E'\n', 'g'), '(^|\n)\s*\d{1,2}[.)]\s+', E'\\1', 'g') AS wr_plans, s."блокер" AS wr_blocker, regexp_replace(s."розбіжність_готовності"::text, '"note": ?"\s*ПМ\s+підтвердив[:,.]?\s*', '"note": "', 'i')::jsonb AS wr_gap, pe.total AS pe_total, pe.done AS pe_done, pe.not_done AS pe_not_done, pe.no_answer AS pe_no_answer, pe.pending AS pe_pending, pe.exec_pct AS pe_pct, pe.signal AS pe_signal, pe.max_carry AS pe_carry, v.etc_gap_signal, v.etc_gap_hours, v.etc_gap_pct_bac, v.stage_etc_signal, public.archi_rules($1::uuid) AS rules, (SELECT json_object_agg(p."стадія", p."дата_план") FROM public.payment_schedule p WHERE p.company_id = m.company_id AND p.project_id = m.project_id AND p."подія" = 'документація') AS doc_deadlines_plan, wp.prev_week AS wp_prev_week, wp.ready_prev_pct AS wp_ready_prev, wp.ready_pct AS wp_ready, wp.d_ready_pp AS wp_d_ready_pp, wp.hours AS wp_hours, wp.cost_uah AS wp_cost, wp.value_uah AS wp_value, wp.result_uah AS wp_result, wp.idx AS wp_idx, wp.signal AS wp_signal, wp.budget_uah AS wp_budget, wp.customer_money_uah AS wp_customer, wp.owner_money_uah AS wp_owner, (SELECT json_agg(json_build_array(h.week_start, h.prev_week, h.d_ready_pp, h.hours, h.cost_uah, h.budget_uah, h.customer_money_uah, h.owner_money_uah) ORDER BY h.week_start) FROM (SELECT * FROM public.archi_weekly_progress x WHERE x.company_id = m.company_id AND x.project_id = m.project_id ORDER BY x.week_start DESC LIMIT 12) h) AS wp_hist FROM public.project_metrics m LEFT JOIN LATERAL (SELECT * FROM public.wr_weekly_snapshots w WHERE w.company_id = m.company_id AND w.project_id = m.project_id ORDER BY w.week_start DESC LIMIT 1) s ON true LEFT JOIN public.archi_plan_execution pe ON pe.company_id = m.company_id AND pe.project_id = m.project_id AND pe.week_start = s.week_start LEFT JOIN public.archi_report_today v ON v.company_id = m.company_id AND v.project_id = m.project_id LEFT JOIN public.archi_weekly_progress wp ON wp.company_id = m.company_id AND wp.project_id = m.project_id AND wp.week_start = s.week_start WHERE m.company_id = $1::uuid ORDER BY m.project_id;